def hint(secret, guess):
    if guess < secret:
        return "higher"
    elif guess > secret:
        return "lower"
    else:
        return "correct"


def read_guess(text):
    cleaned = text.strip()
    if cleaned.isdecimal():
        value = int(cleaned)
        if 1 <= value <= 100:
            return value
    return None


def play(secret):
    used = 0
    while used < 5:
        text = input()
        guess = read_guess(text)
        if guess is None:
            print("Please type a whole number from 1 to 100.")
            continue
        used += 1
        result = hint(secret, guess)
        if result == "correct":
            print(f"Correct! Guesses used: {used}")
            return
        print(result)
    print(f"Out of guesses. It was {secret}.")


if __name__ == "__main__":
    play(int(input()))

